stages.sampleAnswer:
POST /posts
  body: { caption: string, mediaUrl: string }
  → 201 { postId, createdAt }

GET /feed
  → 200 { posts: Post[], nextCursor: string }

POST /stories
  body: { mediaUrl: string }
  → 201 { storyId, expiresAt }

POST /messages
  body: { recipientId: string, content: string }
  → 201 { messageId, sentAt }

GET /messages/:conversationId
  → 200 { messages: Message[] }
